import socket, concurrent.futures as cf
hosts=['172.24.0.1','172.24.0.2','172.24.0.3','172.24.0.5','172.24.0.6']
ports=list(range(1,10000))
def check(hp):
    h,p=hp
    s=socket.socket(); s.settimeout(0.4)
    try:
        if s.connect_ex((h,p))==0: return (h,p)
    finally: s.close()
    return None
work=[(h,p) for h in hosts for p in ports]
found=[]
with cf.ThreadPoolExecutor(200) as ex:
    for r in ex.map(check, work):
        if r: found.append(r)
print(sorted(found))
EOF"}

